class Counter {
    private int count;
    synchronized void increment() { count++; }
    synchronized int value() { return count; }
}
Counter counter = new Counter();
Runnable work = () -> {
    for (int i = 0; i < 4; i++) counter.increment();
};
Thread first = new Thread(work);
Thread second = new Thread(work);
first.start();
second.start();
first.join();
second.join();
